mapper.select:
SELECT ss.*
FROM slot_sessions ss
WHERE ss.assignment_id = #{assignmentId}
  AND ss.start_at >= #{startAt}
  AND ss.end_at <= #{endAt}
ORDER BY ss.start_at ASC, ss.session_number ASC

SELECT * FROM slot_sessions WHERE slot_id = #{slotId}
AND (start_at < #{startAt} OR end_at > #{endAt})
ORDER BY session_number ASC

mapper.delete:
DELETE FROM slot_sessions
WHERE slot_id = #{slotId}

  AND (start_at < #{startAt} OR end_at > #{endAt})

